public class Main {
    public static void tambahBonus(int poin) {   // poin: parameter, lokal di method ini
        int bonus = poin * 2;                    // bonus: variabel lokal
        System.out.println("Bonus di dalam method: " + bonus);
    }

    public static void main(String[] args) {
        int poin = 10;                           // poin milik main, berbeda dari poin di tambahBonus
        tambahBonus(poin);
        // System.out.println(bonus);            // error: cannot find symbol
        {
            int sementara = 99;                  // blok bebas punya scope sendiri
            System.out.println("Di dalam blok: " + sementara);
        }
        // System.out.println(sementara);        // error: cannot find symbol
        System.out.println("poin di main: " + poin);
    }
}

