abstract class Bentuk {
    private final String nama;

    Bentuk(String nama) {
        this.nama = nama;
    }

    abstract double luas();                 // wajib diisi subclass

    String info() {                         // dipakai bersama
        return nama + ": " + Math.round(luas() * 100) / 100.0;
    }
}

class Lingkaran extends Bentuk {
    double r;

    Lingkaran(double r) {
        super("Lingkaran");
        this.r = r;
    }

    @Override
    double luas() {
        return Math.PI * r * r;
    }
}

class Persegi extends Bentuk {
    double s;

    Persegi(double s) {
        super("Persegi");
        this.s = s;
    }

    @Override
    double luas() {
        return s * s;
    }
}

