    interface Sapaan {
        void sapa();
    }

    public static void main(String[] args) {
        Luar o = new Luar();
        System.out.println(new Pembantu().sapa());
        Luar.Dalam d = o.new Dalam();
        System.out.println(d.ambil());
        Sapaan s = new Sapaan() {     // anonymous class
            @Override
            public void sapa() { System.out.println("anonim jalan"); }
        };
        s.sapa();
    }
}

