        List<String> a = new ArrayList<>(List.of("x", "x", "y", "x"));
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i).equals("x")) {
                a.remove(i);
            }
        }
        System.out.println("Maju (bug)  : " + a);

        // Cara 2: mundur dari belakang
        List<String> b = new ArrayList<>(List.of("x", "x", "y", "x"));
        for (int i = b.size() - 1; i >= 0; i--) {
            if (b.get(i).equals("x")) {
                b.remove(i);
            }
        }
        System.out.println("Mundur      : " + b);

        // Cara 3: salin yang ingin disimpan ke list baru
        List<String> c = new ArrayList<>();
        for (String s : List.of("x", "x", "y", "x")) {
            if (!s.equals("x")) {
                c.add(s);
            }
        }
        System.out.println("List baru   : " + c);
    }
}

