import java.util.*;

public class Main {
    static long panggilan = 0;
    static long fib(int n) { panggilan++; return n < 2 ? n : fib(n - 1) + fib(n - 2); }
    static long fibMemo(int n, Map<Integer, Long> m) {
        panggilan++;
        if (n < 2) return n;
        Long c = m.get(n);
        if (c != null) return c;
        long v = fibMemo(n - 1, m) + fibMemo(n - 2, m);
        m.put(n, v);
        return v;
    }
    static int fpb(int a, int b) { return b == 0 ? a : fpb(b, a % b); }

    public static void main(String[] args) throws Exception {
        long t0 = System.nanoTime();
        long a = fib(32);
        long naif = panggilan;
        panggilan = 0;
        long b = fibMemo(32, new HashMap<>());
        System.out.println("fib(32) = " + a + " = " + b);
        System.out.println("Panggilan naif: " + naif + ", dengan memo: " + panggilan);
        System.out.println("FPB(84, 36) = " + fpb(84, 36));
    }
}

