import java.util.Arrays;

public class Main {
    static int hari(int[] p, int kap) {
        int h = 1, isi = 0;
        for (int x : p) { if (isi + x > kap) { h++; isi = 0; } isi += x; }
        return h;
    }

    public static void main(String[] args) throws Exception {
        int[] paket = {12, 7, 9, 15, 4, 8, 10};
        int lo = Arrays.stream(paket).max().getAsInt(), hi = Arrays.stream(paket).sum();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (hari(paket, mid) <= 3) hi = mid; else lo = mid + 1;
        }
        System.out.println("Kapasitas minimum: " + lo + " (butuh " + hari(paket, lo) + " hari)");
    }
}

